begin;

update public.source_workbooks
set is_current = false
where source_label = 'Inversión publicitaria Ecuador'
  and id <> 'f8f920cd-8c07-5713-98f1-19fb63c8cb4f'::uuid;

   '2026-01-01'::date, '2026-06-30'::date, '{"source":"Excel entregado por el usuario","sheets":[{"name":"MEDIOS","rows":4431,"columns":19},{"name":"MESES","rows":4431,"columns":17},{"name":"ANUNCIANTES","rows":3692,"columns":10},{"name":"Hoja1","rows":19,"columns":10},{"name":"macro","rows":8319,"columns":12}],"currency":"USD"}'::jsonb)
on conflict (id) do update set
  file_name = excluded.file_name,
